""" Script d'entrée unique pour lancer l'ingestion et l'application des corporate actions (équivalent à 'python -m corporate_actions run'). """ from corporate_actions.cli import _run_all, _build_parser import logging import sys
def main(): logging.basicConfig( level=logging.INFO, format="%(asctime)s %(levelname)-8s %(name)s -- %(message)s", ) parser = _build_parser() args = parser.parse_args() # Force la commande 'run' même si non précisée if not hasattr(args, 'command') or args.command != 'run': args.command = 'run' _run_all(args)
if __name__ == "__main__": main()

"""Fonctions utilitaires d'audit pour execution_engine.""" from __future__ import annotations
import json import uuid from datetime import datetime, timezone from typing import Any
from execution_engine.models import ( BrokerOrder, ExecutionEvent, ExecutionFill, OrderIntent, OrderStatus, )
def build_run_id() -> str: return uuid.uuid4().hex[:16]
def make_event( exec_run_id: str, event_type: str, message: str, *, symbol: str | None = None, broker_order_id: str | None = None, intent_id: str | None = None, payload: dict[str, Any] | None = None, ) -> ExecutionEvent: return ExecutionEvent( event_id=uuid.uuid4().hex[:16], exec_run_id=exec_run_id, symbol=symbol, event_type=event_type, message=message[:255], broker_order_id=broker_order_id, intent_id=intent_id, payload_json=json.dumps(payload) if payload else None, created_at=datetime.now(timezone.utc), )
def order_intent_to_db_dict(intent: OrderIntent, exec_run_id: str, status: str = OrderStatus.NEW) -> dict[str, Any]: return { "exec_run_id": exec_run_id, "risk_run_id": intent.risk_run_id, "symbol": intent.symbol, "intent_id": intent.intent_id, "parent_intent_id": intent.parent_intent_id, "intent_role": intent.intent_role, "idempotency_key": intent.idempotency_key, "broker_mode": intent.broker_mode, "broker_order_id": None, "client_order_id": intent.idempotency_key, "side": intent.side, "qty": intent.qty, "filled_qty": 0.0, "avg_fill_price": None, "order_type": intent.order_type, "limit_price": intent.limit_price, "stop_price": None, "trail_percent": intent.trail_percent, "decision_price": intent.decision_price, "status": status, "created_at": datetime.now(timezone.utc), "updated_at": datetime.now(timezone.utc), }
def broker_order_to_db_dict(order: BrokerOrder, exec_run_id: str) -> dict[str, Any]: return { "exec_run_id": exec_run_id, "broker_order_id": order.broker_order_id, "client_order_id": order.client_order_id, "intent_id": order.intent_id, "symbol": order.symbol, "side": order.side, "qty": order.qty, "filled_qty": order.filled_qty, "avg_fill_price": order.avg_fill_price, "status": order.status, "order_type": order.order_type, "limit_price": order.limit_price, "stop_price": order.stop_price, "trail_percent": order.trail_percent, "updated_at": datetime.now(timezone.utc), }
def fill_to_db_dict(fill: ExecutionFill, exec_run_id: str) -> dict[str, Any]: return { "exec_run_id": exec_run_id, "fill_id": fill.fill_id, "broker_order_id": fill.broker_order_id, "intent_id": fill.intent_id, "symbol": fill.symbol, "filled_qty": fill.filled_qty, "avg_fill_price": fill.avg_fill_price, "fill_timestamp": fill.fill_timestamp, "decision_price": fill.decision_price, "slippage_bps": fill.slippage_bps, "implementation_shortfall": fill.implementation_shortfall, }
def event_to_db_dict(event: ExecutionEvent) -> dict[str, Any]: return { "event_id": event.event_id, "exec_run_id": event.exec_run_id, "symbol": event.symbol, "event_type": event.event_type, "message": event.message, "broker_order_id": event.broker_order_id, "intent_id": event.intent_id, "payload_json": event.payload_json, "created_at": event.created_at or datetime.now(timezone.utc), }
def build_execution_run_summary( metrics: dict[str, Any], *, started_at: datetime, finished_at: datetime, execution_mode: str, broker_mode: str, account_id: str | None, account_type: str, effective_pdt_rule: str, swing_only: bool, dry_run: bool, allow_outside_rth: bool, ) -> dict[str, Any]: submitted_orders = int(metrics.get("submitted", 0) or 0) filled_orders = int(metrics.get("filled", 0) or 0) targeted_symbols = int(metrics.get("targets", 0) or 0) failed_orders = int(metrics.get("failed", 0) or 0) skipped_orders = int(metrics.get("skipped", 0) or 0) fill_rate = round((filled_orders / submitted_orders), 4) if submitted_orders > 0 else 0.0 return { "run_id": str(metrics.get("exec_run_id", "") or ""), "risk_run_id": str(metrics.get("risk_run_id", "") or "") or None, "trade_date": metrics.get("trade_date"), "started_at": started_at.isoformat(timespec="seconds"), "finished_at": finished_at.isoformat(timespec="seconds"), "duration_seconds": round((finished_at - started_at).total_seconds(), 2), "execution_mode": execution_mode, "broker_mode": broker_mode, "status": str(metrics.get("status", "UNKNOWN") or "UNKNOWN"), "targeted_symbols": targeted_symbols, "submitted_orders": submitted_orders, "filled_orders": filled_orders, "failed_orders": failed_orders, "skipped_orders": skipped_orders, "rebalance_submitted_orders": int(metrics.get("rebalance_submitted", 0) or 0), "rebalance_failed_orders": int(metrics.get("rebalance_failed", 0) or 0), "constraint_blocked_orders": int(metrics.get("constraint_blocked", 0) or 0), "children_deferred_orders": int(metrics.get("children_deferred", 0) or 0), "fill_rate": fill_rate, "total_target_notional": round(float(metrics.get("total_target_notional", 0.0) or 0.0), 2), "total_initial_risk_dollars": round(float(metrics.get("total_initial_risk_dollars", 0.0) or 0.0), 2), "total_risk_budget_dollars": round(float(metrics.get("total_risk_budget_dollars", 0.0) or 0.0), 2), "max_target_weight": round(float(metrics.get("max_target_weight", 0.0) or 0.0), 4), "targets_with_risk_controls": int(metrics.get("targets_with_risk_controls", 0) or 0), "stale_price_targets": int(metrics.get("stale_price_targets", 0) or 0), "account_type": account_type, "effective_pdt_rule": effective_pdt_rule, "swing_only": bool(swing_only), "dry_run": bool(dry_run), "allow_outside_rth": bool(allow_outside_rth), "account_id": account_id, }

