@st.cache_data(ttl=60, show_spinner=False) def get_risk_run_ids() -> list[str]: df = safe_query("SELECT DISTINCT run_id FROM risk_decisions ORDER BY run_id DESC LIMIT 50") return df["run_id"].tolist() if not df.empty else []
@st.cache_data(ttl=60, show_spinner=False) def get_risk_decisions(run_id: str | None = None) -> pd.DataFrame: if run_id: return safe_query(""" SELECT * FROM risk_decisions WHERE run_id = :run_id ORDER BY COALESCE(candidate_rank, 999999), created_at DESC """, {"run_id": run_id}) return safe_query("SELECT * FROM risk_decisions ORDER BY COALESCE(candidate_rank, 999999), created_at DESC LIMIT 200")
@st.cache_data(ttl=60, show_spinner=False) def get_portfolio_targets(run_id: str | None = None) -> pd.DataFrame: if run_id: return safe_query(""" SELECT * FROM portfolio_targets WHERE run_id = :run_id ORDER BY COALESCE(decision_rank, 999999), target_weight DESC, symbol ASC """, {"run_id": run_id}) return safe_query(""" SELECT * FROM portfolio_targets WHERE run_id = (SELECT run_id FROM portfolio_targets ORDER BY created_at DESC LIMIT 1) ORDER BY COALESCE(decision_rank, 999999), target_weight DESC, symbol ASC """)
# --------------------------------------------------------------------------- # Execution # ---------------------------------------------------------------------------
@st.cache_data(ttl=60, show_spinner=False) def get_execution_runs(limit: int = 20, account_id: str | None = None) -> pd.DataFrame: if account_id: return safe_query(f""" SELECT exec_run_id, risk_run_id, trade_date, broker_mode, dry_run, status, started_at, completed_at, total_targets, total_submitted, total_filled, error_message, account_id FROM execution_runs WHERE account_id = :account_id ORDER BY started_at DESC LIMIT {limit} """, {"account_id": account_id}) return safe_query(f""" SELECT exec_run_id, risk_run_id, trade_date, broker_mode, dry_run, status, started_at, completed_at, total_targets, total_submitted, total_filled, error_message FROM execution_runs ORDER BY started_at DESC LIMIT {limit} """)
@st.cache_data(ttl=60, show_spinner=False) def get_execution_events(exec_run_id: str | None = None) -> pd.DataFrame: if exec_run_id: return safe_query(""" SELECT event_type, symbol, message, payload_json, created_at FROM execution_events WHERE exec_run_id = :eid ORDER BY created_at DESC """, {"eid": exec_run_id}) return safe_query("SELECT event_type, symbol, message, payload_json, created_at FROM execution_events ORDER BY created_at DESC LIMIT 100")
@st.cache_data(ttl=60, show_spinner=False) def get_execution_orders(exec_run_id: str | None = None) -> pd.DataFrame: if exec_run_id: return safe_query( """ SELECT exec_run_id, risk_run_id, symbol, intent_id, parent_intent_id, intent_role, broker_order_id, side, qty, filled_qty, avg_fill_price, order_type, limit_price, stop_price, trail_percent, decision_price, status, created_at, updated_at FROM execution_orders WHERE exec_run_id = :eid ORDER BY CASE WHEN parent_intent_id IS NULL THEN 0 ELSE 1 END, COALESCE(parent_intent_id, intent_id), created_at DESC """, {"eid": exec_run_id}, ) return safe_query( """ SELECT exec_run_id, risk_run_id, symbol, intent_id, parent_intent_id, intent_role, broker_order_id, side, qty, filled_qty, avg_fill_price, order_type, limit_price, stop_price, trail_percent, decision_price, status, created_at, updated_at FROM execution_orders ORDER BY created_at DESC LIMIT 200 """ )
@st.cache_data(ttl=60, show_spinner=False) def get_execution_account_constraints(exec_run_id: str) -> dict[str, object]: df = safe_query( """ SELECT message, payload_json, created_at FROM execution_events WHERE exec_run_id = :eid AND event_type = 'ACCOUNT_CONSTRAINT_APPLIED' ORDER BY created_at DESC LIMIT 1 """, {"eid": exec_run_id}, ) if df.empty: return {}
row = df.iloc[0] payload_raw = row.get("payload_json") payload: dict[str, object] = {} if isinstance(payload_raw, str) and payload_raw.strip(): try: parsed = json.loads(payload_raw) if isinstance(parsed, dict): payload = parsed except Exception: payload = {} payload.setdefault("message", row.get("message", "")) payload.setdefault("created_at", row.get("created_at")) return payload
@st.cache_data(ttl=60, show_spinner=False) def get_broker_positions(account_id: str | None = None) -> pd.DataFrame: if account_id: return safe_query(""" SELECT bps.* FROM broker_positions_snapshots bps INNER JOIN ( SELECT MAX(created_at) AS mx FROM broker_positions_snapshots WHERE account_id = :account_id ) t ON bps.created_at = t.mx WHERE bps.account_id = :account_id ORDER BY market_value DESC """, {"account_id": account_id}) return safe_query(""" SELECT bps.* FROM broker_positions_snapshots bps INNER JOIN (SELECT MAX(created_at) AS mx FROM broker_positions_snapshots) t ON bps.created_at = t.mx ORDER BY market_value DESC """)
@st.cache_data(ttl=60, show_spinner=False) def get_execution_fills(exec_run_id: str | None = None) -> pd.DataFrame: if exec_run_id: return safe_query(""" SELECT * FROM execution_fills WHERE exec_run_id = :eid ORDER BY fill_timestamp DESC """, {"eid": exec_run_id}) return safe_query("SELECT * FROM execution_fills ORDER BY fill_timestamp DESC LIMIT 100")
